def k3(ws, cap):
    n = len(ws)
    dp = [[0] * (cap + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for c in range(cap + 1):
            dp[i][c] = dp[i - 1][c]
            if ws[i - 1] <= c:
                dp[i][c] = dp[i - 1][c - ws[i - 1]] + 1
    return dp
