        self.l = None
        self.r = None
    def ins(self, v):
        if v < self.v:
            if self.l is None:
                self.l = BT2(v)
            else:
                self.l.ins(v)
        else:
            if self.r is None:
                self.r = BT2(v)
            else:
                self.r.ins(v)
    def collect(self, out):
        if self.l is not None:
            self.l.collect(out)
        out.append(self.v)
        if self.r is not None:
            self.r.collect(out)
        return out
